BASELINE = {"allowed_public_ports": {443}, "required_tags": {"owner", "data_class"}}

security_groups = [
    {"id": "sg-web", "tags": {"owner": "trade", "data_class": "public"},
     "ingress": [{"cidr": "0.0.0.0/0", "port": 443}]},
    {"id": "sg-batch", "tags": {"owner": "data"},
     "ingress": [{"cidr": "0.0.0.0/0", "port": 22}, {"cidr": "10.0.0.0/8", "port": 5432}]},
]

def check(sg):
    issues = []
    for rule in sg["ingress"]:
        if rule["cidr"] == "0.0.0.0/0" and rule["port"] not in BASELINE["allowed_public_ports"]:
            issues.append(f"외부 노출: {rule['port']}/tcp 가 인터넷 전체에 열림")
    missing = BASELINE["required_tags"] - sg["tags"].keys()
    if missing:
        issues.append(f"태그 누락: {sorted(missing)}")
    return issues

for sg in security_groups:
    print(sg["id"], check(sg) or "기준 충족")
